{
  "name": "Pocket Lab Scanner",
  "description": "A professional-grade mobile extraoral dental scanner app that converts smartphone photos of plaster models into high-precision STL/OBJ files for CAD/CAM dental labs.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ScannerState {
  IDLE = 'IDLE',
  CALIBRATING = 'CALIBRATING',
  SCANNING = 'SCANNING',
  PROCESSING = 'PROCESSING',
  COMPLETED = 'COMPLETED'
}

export interface CaptureFrame {
  id: string;
  dataUrl: string;
  timestamp: number;
  angle: number; // 0-359
}

export interface ScanResult {
  id: string;
  stlUrl?: string;
  objUrl?: string;
  plyUrl?: string;
  previewImageUrl: string;
  accuracy: number; // e.g., 0.98 for 98%
  timestamp: number;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeScanQuality(images: string[]) {
  const model = 'gemini-3-flash-preview';

  // We send a subset of images to Gemini to verify if the calibration markers are visible
  // and if the plaster model edges are sharp enough for marginal line detection.
  const imageParts = images.slice(0, 3).map(img => ({
    inlineData: {
      mimeType: 'image/jpeg',
      data: img.split(',')[1]
    }
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...imageParts,
        { text: "Analyze these frames from a dental plaster model scan. Check for: 1. Visibility of ArUco markers for scale. 2. Sharpness of the cervical margins. 3. Lighting consistency. Return a JSON with qualityScore (0-100), feedback (string), and missingAngles (array of numbers if any)." }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          qualityScore: { type: Type.NUMBER },
          feedback: { type: Type.STRING },
          missingAngles: { 
            type: Type.ARRAY,
            items: { type: Type.NUMBER }
          }
        },
        required: ["qualityScore", "feedback"]
      }
    }
  });

  return JSON.parse(response.text);
}

export async function generateTechBrief() {
  const model = 'gemini-3-pro-preview';
  const response = await ai.models.generateContent({
    model,
    contents: "Explain the photogrammetry pipeline for a dental plaster model using ArUco markers for 1:1 scale calibration. Focus on STL export for Exocad."
  });
  return response.text;
}

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { ScannerState, CaptureFrame } from '../types';

interface ScannerViewProps {
  onCapture: (frame: CaptureFrame) => void;
  onFinished: () => void;
  state: ScannerState;
}

const ScannerView: React.FC<ScannerViewProps> = ({ onCapture, onFinished, state }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [coverage, setCoverage] = useState(0);
  const [frameCount, setFrameCount] = useState(0);

  useEffect(() => {
    async function setupCamera() {
      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      }
    }
    if (state === ScannerState.SCANNING) {
      setupCamera();
    }

    return () => {
      if (videoRef.current && videoRef.current.srcObject) {
        const stream = videoRef.current.srcObject as MediaStream;
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [state]);

  const captureFrame = useCallback(() => {
    if (!videoRef.current || !canvasRef.current) return;

    const context = canvasRef.current.getContext('2d');
    if (context) {
      context.drawImage(videoRef.current, 0, 0, 640, 480);
      const dataUrl = canvasRef.current.toDataURL('image/jpeg', 0.8);

      const newFrame: CaptureFrame = {
        id: Date.now().toString(),
        dataUrl,
        timestamp: Date.now(),
        angle: (frameCount * 15) % 360 // Mocking angle calculation
      };

      onCapture(newFrame);
      setFrameCount(prev => prev + 1);
      setCoverage(prev => Math.min(100, prev + 2.5));

      if (coverage >= 98) {
        onFinished();
      }
    }
  }, [frameCount, coverage, onCapture, onFinished]);

  useEffect(() => {
    let interval: number;
    if (state === ScannerState.SCANNING) {
      interval = window.setInterval(captureFrame, 500);
    }
    return () => clearInterval(interval);
  }, [state, captureFrame]);

  return (
    <div className="relative w-full h-full bg-black rounded-3xl overflow-hidden shadow-2xl border-4 border-slate-700">
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        className="w-full h-full object-cover"
      />

      <canvas ref={canvasRef} width="640" height="480" className="hidden" />

      {/* AR Overlays */}
      <div className="absolute inset-0 pointer-events-none flex flex-col justify-between p-6">
        <div className="flex justify-between items-start">
          <div className="bg-black/60 backdrop-blur-md p-3 rounded-xl border border-white/20">
            <p className="text-xs uppercase font-bold text-blue-400">Resolution</p>
            <p className="text-xl font-mono">4K Ultra HD</p>
          </div>
          <div className="bg-black/60 backdrop-blur-md p-3 rounded-xl border border-white/20 text-right">
            <p className="text-xs uppercase font-bold text-green-400">Coverage</p>
            <p className="text-2xl font-mono">{Math.floor(coverage)}%</p>
          </div>
        </div>

        {/* Framing Guide */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 border-2 border-dashed border-white/30 rounded-full flex items-center justify-center">
            <div className="w-4 h-4 bg-blue-500 rounded-full animate-ping" />
            <p className="absolute bottom-[-40px] text-xs font-semibold whitespace-nowrap bg-blue-600 px-3 py-1 rounded-full uppercase tracking-widest">Center the Plaster Model</p>
        </div>

        <div className="w-full h-2 bg-white/10 rounded-full overflow-hidden mb-4">
          <div 
            className="h-full bg-gradient-to-r from-blue-500 to-cyan-400 transition-all duration-300" 
            style={{ width: `${coverage}%` }}
          />
        </div>
      </div>
    </div>
  );
};

export default ScannerView;

