                      <svg className="w-10 h-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                      </svg>
                    </div>
                    <h2 className="text-3xl font-bold">Reconstruction Ready</h2>
                    <p className="text-green-400 font-mono mt-2">Accuracy: ±25µm (Clinical Grade)</p>
                  </div>
                </div>
                <div className="p-6 bg-slate-900 grid grid-cols-3 gap-4 border-t border-slate-700">
