                <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full" />
                Automatic Water-tight (Manifold) Meshes
              </li>
            </ul>
          </div>

          <div className="flex-1 border-2 border-slate-800 rounded-3xl p-6 relative overflow-hidden group">
            <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/10 blur-3xl group-hover:bg-blue-600/20 transition-all" />
