      const newFrame: CaptureFrame = {
        id: Date.now().toString(),
        dataUrl,
        timestamp: Date.now(),
        angle: (frameCount * 15) % 360
      };

      onCapture(newFrame);
      setFrameCount(prev => prev + 1);
      setCoverage(prev => Math.min(100, prev + 2.5));

      if (coverage >= 98) {
        onFinished();
      }
    }
  }, [frameCount, coverage, onCapture, onFinished]);

  useEffect(() => {
    let interval: number;
    if (state === ScannerState.SCANNING) {
      interval = window.setInterval(captureFrame, 500);
    }
    return () => clearInterval(interval);
  }, [state, captureFrame]);

  return (
    <div className="relative w-full h-full bg-black rounded-3xl overflow-hidden shadow-2xl border-4 border-slate-700">
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        className="w-full h-full object-cover"
      />

      <canvas ref={canvasRef} width="640" height="480" className="hidden" />

      <div className="absolute inset-0 pointer-events-none flex flex-col justify-between p-6">
        <div className="flex justify-between items-start">
          <div className="bg-black/60 backdrop-blur-md p-3 rounded-xl border border-white/20">
            <p className="text-xs uppercase font-bold text-blue-400">{t.resolution}</p>
            <p className="text-xl font-mono">4K Ultra HD</p>
          </div>
          <div className="bg-black/60 backdrop-blur-md p-3 rounded-xl border border-white/20 text-right">
            <p className="text-xs uppercase font-bold text-green-400">{t.coverage}</p>
            <p className="text-2xl font-mono">{Math.floor(coverage)}%</p>
          </div>
        </div>

        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 border-2 border-dashed border-white/30 rounded-full flex items-center justify-center">
            <div className="w-4 h-4 bg-blue-500 rounded-full animate-ping" />
