interface ScannerViewProps {
  onCapture: (frame: CaptureFrame) => void;
  onFinished: () => void;
  state: ScannerState;
  lang: Language;
}

const SECTOR_COUNT = 24; // 15 degrees each
const LIGHT_THRESHOLDS = {
  DARK: 65,
  BRIGHT: 220
};

