      brightness += (data[i] + data[i+1] + data[i+2]) / 3;
    }

    const avgBrightness = brightness / (data.length / (4 * sampleSize));

    if (avgBrightness < LIGHT_THRESHOLDS.DARK) {
      setLightingStatus('dark');
