          <defs>
            <filter id="glow">
              <feGaussianBlur stdDeviation="1.5" result="coloredBlur"/>
              <feMerge>
                <feMergeNode in="coloredBlur"/>
                <feMergeNode in="SourceGraphic"/>
              </feMerge>
            </filter>
            <linearGradient id="boxGradient" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="#3b82f6" stopOpacity="0.2" />
              <stop offset="100%" stopColor="#2dd4bf" stopOpacity="0.2" />
            </linearGradient>
          </defs>

          {/* Simulated 3D Bounding Box Overlay */}
          <g transform="translate(50, 50)" opacity="0.6">
            <rect x="-15" y="-15" width="30" height="30" fill="none" stroke="white" strokeWidth="0.2" strokeDasharray="1 1" />
            <rect x="-12" y="-25" width="24" height="24" fill="none" stroke="#3b82f6" strokeWidth="0.3" />
            <line x1="-15" y1="-15" x2="-12" y2="-25" stroke="#3b82f6" strokeWidth="0.2" />
            <line x1="15" y1="-15" x2="12" y2="-25" stroke="#3b82f6" strokeWidth="0.2" />
