import React, { useState } from 'react';
import { translations, Language } from '../translations';
import { GoogleGenAI } from "@google/genai";

interface KnowledgeHubProps {
  lang: Language;
}

const KnowledgeHub: React.FC<KnowledgeHubProps> = ({ lang }) => {
  const t = translations[lang].knowledge;
  const [question, setQuestion] = useState('');
  const [answer, setAnswer] = useState('');
  const [isAsking, setIsAsking] = useState(false);

  const askAI = async () => {
    if (!question) return;
    setIsAsking(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `You are a dental technical assistant. Answer the following question about dental scanning and 3D formats (STL, PLY, OBJ) for a professional dentist. Answer in ${lang === 'es' ? 'Spanish' : lang === 'pt' ? 'Portuguese' : 'English'}. Question: ${question}`,
        config: { thinkingConfig: { thinkingBudget: 0 } }
      });
      setAnswer(response.text || 'No response');
    } catch (e) {
      setAnswer('Error connecting to Assistant.');
    } finally {
      setIsAsking(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="text-center">
        <h2 className="text-4xl font-black mb-4 bg-gradient-to-r from-white to-slate-500 bg-clip-text text-transparent uppercase tracking-tight">
          {t.title}
        </h2>
        <p className="text-slate-400 text-lg">
          {lang === 'es' ? 'Comprenda los estándares de la odontología digital moderna.' : 'Understand the standards of modern digital dentistry.'}
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {[
          { id: 'stl', title: t.stl, desc: t.stlDesc, icon: '📐', color: 'from-blue-600/20 to-blue-900/40' },
          { id: 'ply', title: t.ply, desc: t.plyDesc, icon: '🎨', color: 'from-purple-600/20 to-purple-900/40' },
          { id: 'obj', title: t.obj, desc: t.objDesc, icon: '🧊', color: 'from-emerald-600/20 to-emerald-900/40' },
        ].map(format => (
          <div key={format.id} className={`p-8 rounded-3xl bg-gradient-to-br ${format.color} border border-white/10 hover:border-white/30 transition-all group`}>
            <div className="text-4xl mb-6 group-hover:scale-125 transition-transform inline-block">{format.icon}</div>
            <h3 className="text-xl font-bold mb-3">{format.title}</h3>
            <p className="text-sm text-slate-300 leading-relaxed">{format.desc}</p>
          </div>
        ))}
      </div>

      <div className="bg-slate-800/40 rounded-3xl border border-slate-700 p-8">
        <div className="flex items-center gap-3 mb-6">
          <div className="w-10 h-10 bg-blue-600 rounded-full flex items-center justify-center">
            <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
          </div>
          <h3 className="text-xl font-bold">{t.askAI}</h3>
        </div>

        <div className="flex flex-col gap-4">
          <textarea 
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
            placeholder={lang === 'es' ? '¿Cuál es la diferencia entre STL y PLY para Exocad?' : 'What is the difference between STL and PLY for Exocad?'}
            className="bg-slate-900/80 border border-slate-700 rounded-2xl p-4 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all resize-none h-24"
          />
          <button 
            onClick={askAI}
            disabled={isAsking}
            className="bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white font-bold py-3 px-6 rounded-xl transition-all self-end"
          >
            {isAsking ? '...' : (lang === 'es' ? 'Preguntar' : 'Ask Assistant')}
          </button>

          {answer && (
            <div className="mt-4 p-5 bg-blue-900/30 border border-blue-500/30 rounded-2xl text-blue-100 text-sm leading-relaxed animate-in fade-in zoom-in-95">
              {answer}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default KnowledgeHub;

import React, { useState, useCallback } from 'react';
import AppHeader from './components/AppHeader';
import ScannerView from './components/ScannerView';
import KnowledgeHub from './components/KnowledgeHub';
import { ScannerState, CaptureFrame, ScanResult } from './types';
import { analyzeScanQuality } from './services/geminiScannerService';
import { translations, Language } from './translations';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('es');
  const [view, setView] = useState<'scanner' | 'knowledge'>('scanner');
  const [scannerState, setScannerState] = useState<ScannerState>(ScannerState.IDLE);
  const [capturedFrames, setCapturedFrames] = useState<CaptureFrame[]>([]);
  const [lastResult, setLastResult] = useState<ScanResult | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [feedback, setFeedback] = useState<string>('');

  const t = translations[lang];

  const handleStartScan = () => {
    setCapturedFrames([]);
    setScannerState(ScannerState.SCANNING);
    setFeedback(lang === 'es' ? 'Mueva el celular lentamente alrededor del modelo.' : 'Move your phone slowly around the model.');
  };

  const handleFrameCapture = useCallback((frame: CaptureFrame) => {
    setCapturedFrames(prev => [...prev, frame]);
  }, []);

  const handleScanFinished = async () => {
    setScannerState(ScannerState.PROCESSING);
    setIsProcessing(true);
    setFeedback(t.scanner.processing);

    try {
      const analysis = await analyzeScanQuality(capturedFrames.map(f => f.dataUrl), lang);

      if (analysis.qualityScore > 70) {
        setFeedback(t.scanner.reconstructing);
        // Simulación de reconstrucción pesada
        setTimeout(() => {
          setLastResult({
            id: 'SCAN-' + Date.now(),
            accuracy: 0.992,
            previewImageUrl: capturedFrames[0].dataUrl,
            timestamp: Date.now(),
            stlUrl: '#',
            plyUrl: '#'
          });
          setScannerState(ScannerState.COMPLETED);
          setIsProcessing(false);
          setFeedback(t.scanner.complete);
        }, 4000);
      } else {
        setScannerState(ScannerState.IDLE);
        setIsProcessing(false);
        setFeedback(`${t.scanner.failed}: ${analysis.feedback}`);
      }
    } catch (error) {
      setScannerState(ScannerState.IDLE);
      setIsProcessing(false);
      setFeedback('Error...');
    }
  };

  return (
    <div className="flex flex-col min-h-screen">
      <AppHeader lang={lang} setLang={setLang} currentView={view} setView={setView} />

      <main className="flex-1 max-w-7xl mx-auto w-full p-4 md:p-8">
        {view === 'knowledge' ? (
          <KnowledgeHub lang={lang} />
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">
            <div className="lg:col-span-8 flex flex-col gap-6">
              <div className="aspect-[4/3] w-full relative">
                {scannerState === ScannerState.IDLE && (
                  <div className="absolute inset-0 bg-slate-800/50 rounded-3xl flex flex-col items-center justify-center p-8 border-2 border-dashed border-slate-700 overflow-hidden">
                    <div className="w-24 h-24 bg-blue-600/20 text-blue-500 rounded-full flex items-center justify-center mb-6 relative">
                      <div className="absolute inset-0 bg-blue-500 rounded-full animate-ping opacity-20" />
                      <svg className="w-12 h-12 relative z-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" />
                      </svg>
                    </div>
                    <h2 className="text-2xl font-bold mb-2">{t.scanner.readyTitle}</h2>
                    <p className="text-slate-400 text-center max-w-sm mb-8">{t.scanner.readyDesc}</p>
                    <button 
                      onClick={handleStartScan}
                      className="bg-blue-600 hover:bg-blue-500 text-white font-bold py-4 px-10 rounded-2xl shadow-xl shadow-blue-500/20 transition-all transform hover:scale-105 active:scale-95"
                    >
                      {t.scanner.startBtn}
                    </button>
                  </div>
                )}

                {(scannerState === ScannerState.SCANNING || scannerState === ScannerState.PROCESSING) && (
                  <ScannerView 
                    state={scannerState} 
                    onCapture={handleFrameCapture} 
                    onFinished={handleScanFinished} 
                    lang={lang}
                  />
                )}

                {scannerState === ScannerState.COMPLETED && lastResult && (
                  <div className="absolute inset-0 bg-slate-800 rounded-3xl overflow-hidden flex flex-col animate-in zoom-in-95 duration-500">
                    <div className="relative flex-1">
                      <img src={lastResult.previewImageUrl} className="w-full h-full object-cover opacity-60" />
                      <div className="absolute inset-0 flex flex-col items-center justify-center">
                        <div className="w-20 h-20 bg-green-500 rounded-full flex items-center justify-center shadow-lg shadow-green-500/30 mb-4 animate-bounce">
                          <svg className="w-10 h-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                          </svg>
                        </div>
                        <h2 className="text-3xl font-bold">{t.scanner.complete}</h2>
                        <p className="text-green-400 font-mono mt-2">{t.scanner.accuracy}</p>
                      </div>
                    </div>
                    <div className="p-6 bg-slate-900 grid grid-cols-3 gap-4 border-t border-slate-700">
                      <button className="flex flex-col items-center gap-2 p-4 bg-slate-800 rounded-xl hover:bg-slate-700 transition-all group">
                        <span className="text-[10px] text-slate-400 uppercase font-bold tracking-wider group-hover:text-blue-400 transition-colors">{t.scanner.exportStl}</span>
                        <span className="font-bold">Exocad</span>
                      </button>
                      <button className="flex flex-col items-center gap-2 p-4 bg-slate-800 rounded-xl hover:bg-slate-700 transition-all group">
                        <span className="text-[10px] text-slate-400 uppercase font-bold tracking-wider group-hover:text-purple-400 transition-colors">{t.scanner.exportObj}</span>
                        <span className="font-bold">Color Mesh</span>
                      </button>
                      <button className="flex flex-col items-center gap-2 p-4 bg-blue-600 rounded-xl hover:bg-blue-500 transition-all">
                        <span className="text-[10px] text-white/60 uppercase font-bold tracking-wider">{t.scanner.sendLab}</span>
                        <span className="font-bold">Portal</span>
                      </button>
                    </div>
                  </div>
                )}
              </div>

              <div className={`p-6 rounded-2xl transition-all duration-500 flex items-center gap-4 ${scannerState === ScannerState.SCANNING ? 'bg-blue-600/10 border border-blue-500/30' : 'bg-slate-800/50'}`}>
                <div className={`w-3 h-3 rounded-full ${scannerState === ScannerState.SCANNING ? 'bg-blue-500 animate-pulse' : scannerState === ScannerState.PROCESSING ? 'bg-yellow-500 animate-pulse' : 'bg-slate-500'}`} />
                <p className="text-sm font-medium text-slate-200">
                  {feedback}
                </p>
              </div>
            </div>

            <div className="lg:col-span-4 flex flex-col gap-6">
              <div className="bg-slate-800/50 p-6 rounded-3xl border border-slate-700">
                <h3 className="text-lg font-bold mb-4 flex items-center gap-2 text-blue-400 uppercase tracking-tight">
                  {t.guide.title}
                </h3>
                <div className="space-y-4">
                  <div className="flex gap-4 p-3 bg-slate-900/50 rounded-xl border border-white/5 group hover:border-white/20 transition-all">
