import React, { useRef, useState, useEffect, useCallback, useMemo } from 'react';
import { ScannerState, CaptureFrame } from '../types';
import { translations, Language } from '../translations';

interface ScannerViewProps {
  onCapture: (frame: CaptureFrame) => void;
  onFinished: () => void;
  state: ScannerState;
  lang: Language;
}

const SECTOR_COUNT = 24; // 15 degrees each
const LIGHT_THRESHOLDS = {
  DARK: 65,
  BRIGHT: 220
};

const ScannerView: React.FC<ScannerViewProps> = ({ onCapture, onFinished, state, lang }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [capturedSectors, setCapturedSectors] = useState<Set<number>>(new Set());
  const [frameCount, setFrameCount] = useState(0);
  const [lightingStatus, setLightingStatus] = useState<'optimal' | 'dark' | 'bright'>('optimal');
  const [showFlash, setShowFlash] = useState(false);
  const [isCapturing, setIsCapturing] = useState(false);
  const t = translations[lang].scanner;

  const coverage = useMemo(() => {
    return (capturedSectors.size / SECTOR_COUNT) * 100;
  }, [capturedSectors.size]);

  useEffect(() => {
    async function setupCamera() {
      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ 
            video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } } 
          });
          if (videoRef.current) {
            videoRef.current.srcObject = stream;
          }
        } catch (err) {
          console.error("Camera access denied", err);
        }
      }
    }
    if (state === ScannerState.SCANNING) {
      setupCamera();
      setCapturedSectors(new Set());
      setFrameCount(0);
    }

    return () => {
      if (videoRef.current && videoRef.current.srcObject) {
        const stream = videoRef.current.srcObject as MediaStream;
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [state]);

  const analyzeLighting = (context: CanvasRenderingContext2D) => {
    const imageData = context.getImageData(0, 0, 640, 480);
    const data = imageData.data;
    let brightness = 0;
    const sampleSize = 20; 

    for (let i = 0; i < data.length; i += 4 * sampleSize) {
      brightness += (data[i] + data[i+1] + data[i+2]) / 3;
    }

    const avgBrightness = brightness / (data.length / (4 * sampleSize));

    if (avgBrightness < LIGHT_THRESHOLDS.DARK) {
      setLightingStatus('dark');
    } else if (avgBrightness > LIGHT_THRESHOLDS.BRIGHT) {
      setLightingStatus('bright');
    } else {
      setLightingStatus('optimal');
    }
  };

  const captureFrame = useCallback(() => {
    if (!videoRef.current || !canvasRef.current || state !== ScannerState.SCANNING) return;

    const context = canvasRef.current.getContext('2d');
    if (context) {
      setShowFlash(true);
      setTimeout(() => setShowFlash(false), 80);

      setIsCapturing(true);
      setTimeout(() => setIsCapturing(false), 300);

      context.drawImage(videoRef.current, 0, 0, 640, 480);
      analyzeLighting(context);

      const dataUrl = canvasRef.current.toDataURL('image/jpeg', 0.8);

      const angle = (frameCount * 15) % 360;
      const sectorIndex = Math.floor(angle / (360 / SECTOR_COUNT));

      const newFrame: CaptureFrame = {
        id: Date.now().toString(),
        dataUrl,
        timestamp: Date.now(),
        angle: angle
      };

      onCapture(newFrame);
      setFrameCount(prev => prev + 1);

      setCapturedSectors(prev => {
        const next = new Set(prev);
        next.add(sectorIndex);

        if (next.size >= SECTOR_COUNT) {
          onFinished();
        }
        return next;
      });
    }
  }, [frameCount, state, onCapture, onFinished]);

  useEffect(() => {
    let interval: number;
    if (state === ScannerState.SCANNING) {
      interval = window.setInterval(captureFrame, 1500); 
    }
    return () => clearInterval(interval);
  }, [state, captureFrame]);

  const nextTargetSector = useMemo(() => {
    for (let i = 0; i < SECTOR_COUNT; i++) {
      if (!capturedSectors.has(i)) return i;
    }
    return -1;
  }, [capturedSectors]);

  if (state === ScannerState.PROCESSING) {
    return (
      <div className="relative w-full h-full bg-slate-900 rounded-3xl overflow-hidden flex flex-col items-center justify-center p-8">
        <div className="relative w-48 h-48 mb-8">
          {/* Simulated 3D Point Cloud Animation */}
          <div className="absolute inset-0 flex items-center justify-center">
            {Array.from({ length: 12 }).map((_, i) => (
              <div 
                key={i}
                className="absolute w-2 h-2 bg-blue-400 rounded-full animate-pulse"
                style={{
                  transform: `rotate(${i * 30}deg) translateY(-40px)`,
                  animationDelay: `${i * 0.1}s`,
                  opacity: 0.4 + Math.random() * 0.6
                }}
              />
            ))}
            <div className="w-24 h-24 border-2 border-blue-500/20 rounded-full animate-spin duration-[3000ms]" />
            <div className="absolute w-16 h-16 border-2 border-cyan-400/30 rounded-full animate-reverse-spin duration-[2000ms]" />
          </div>
          <div className="absolute inset-0 flex items-center justify-center">
             <span className="text-4xl">🦷</span>
          </div>
        </div>
        <h3 className="text-2xl font-bold text-white mb-2 animate-pulse">{t.processing}</h3>
        <p className="text-slate-400 text-sm font-mono tracking-tighter uppercase">{t.reconstructing}</p>

        <style>{`
          @keyframes reverse-spin {
            from { transform: rotate(360deg); }
            to { transform: rotate(0deg); }
          }
          .animate-reverse-spin {
            animation: reverse-spin linear infinite;
          }
        `}</style>
      </div>
    );
  }

  return (
    <div className="relative w-full h-full bg-black rounded-3xl overflow-hidden shadow-2xl border-4 border-slate-700 transition-all">
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        className="w-full h-full object-cover"
      />

      <canvas ref={canvasRef} width="640" height="480" className="hidden" />

      <div className={`absolute inset-0 bg-white transition-opacity duration-75 pointer-events-none z-[100] ${showFlash ? 'opacity-60' : 'opacity-0'}`} />

      {lightingStatus !== 'optimal' && (
        <div className="absolute inset-x-0 top-24 z-50 flex justify-center animate-in fade-in slide-in-from-top-4 duration-500 pointer-events-none">
          <div className={`px-6 py-3 rounded-2xl flex items-center gap-3 shadow-2xl border-2 backdrop-blur-xl ${
            lightingStatus === 'dark' 
              ? 'bg-amber-900/80 border-amber-500/50 text-amber-200' 
              : 'bg-red-900/80 border-red-500/50 text-red-200'
          }`}>
            <span className="text-xl">{lightingStatus === 'dark' ? '🌙' : '☀️'}</span>
            <p className="font-bold text-sm tracking-wide uppercase">
              {lightingStatus === 'dark' ? t.tooDark : t.tooBright}
            </p>
          </div>
        </div>
      )}

      <div className="absolute inset-0 pointer-events-none z-10">
        <svg className="w-full h-full" viewBox="0 0 100 100">
          <defs>
            <filter id="glow">
              <feGaussianBlur stdDeviation="1.5" result="coloredBlur"/>
              <feMerge>
                <feMergeNode in="coloredBlur"/>
                <feMergeNode in="SourceGraphic"/>
              </feMerge>
            </filter>
            <linearGradient id="boxGradient" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="#3b82f6" stopOpacity="0.2" />
              <stop offset="100%" stopColor="#2dd4bf" stopOpacity="0.2" />
            </linearGradient>
          </defs>

          <g transform="translate(50, 50)" opacity="0.6">
            <rect x="-15" y="-15" width="30" height="30" fill="none" stroke="white" strokeWidth="0.2" strokeDasharray="1 1" />
            <rect x="-12" y="-25" width="24" height="24" fill="none" stroke="#3b82f6" strokeWidth="0.3" />
            <line x1="-15" y1="-15" x2="-12" y2="-25" stroke="#3b82f6" strokeWidth="0.2" />
            <line x1="15" y1="-15" x2="12" y2="-25" stroke="#3b82f6" strokeWidth="0.2" />
            <line x1="15" y1="15" x2="12" y2="-1" stroke="#3b82f6" strokeWidth="0.2" />
            <line x1="-15" y1="15" x2="-12" y2="-1" stroke="#3b82f6" strokeWidth="0.2" />
            <path d="M -15 -15 L -12 -25 L 12 -25 L 15 -15 Z" fill="url(#boxGradient)" />
          </g>

          <g transform="translate(50, 50)" stroke="white" strokeWidth="0.5" opacity="0.4">
            <line x1="-5" y1="0" x2="5" y2="0" />
            <line x1="0" y1="-5" x2="0" y2="5" />
          </g>

          <g transform="translate(50, 50)">
            {Array.from({ length: SECTOR_COUNT }).map((_, i) => {
              const startAngle = (i * 360) / SECTOR_COUNT;
              const endAngle = ((i + 1) * 360) / SECTOR_COUNT;
              const isCaptured = capturedSectors.has(i);

              const r1 = 42; 
              const r2 = 38;
              const x1 = r1 * Math.cos((startAngle - 90) * Math.PI / 180);
              const y1 = r1 * Math.sin((startAngle - 90) * Math.PI / 180);
              const x2 = r1 * Math.cos((endAngle - 90) * Math.PI / 180);
              const y2 = r1 * Math.sin((endAngle - 90) * Math.PI / 180);
              const x3 = r2 * Math.cos((endAngle - 90) * Math.PI / 180);
              const y3 = r2 * Math.sin((endAngle - 90) * Math.PI / 180);
              const x4 = r2 * Math.cos((startAngle - 90) * Math.PI / 180);
              const y4 = r2 * Math.sin((startAngle - 90) * Math.PI / 180);

              return (
                <path
                  key={i}
                  d={`M ${x1} ${y1} A ${r1} ${r1} 0 0 1 ${x2} ${y2} L ${x3} ${y3} A ${r2} ${r2} 0 0 0 ${x4} ${y4} Z`}
                  fill={isCaptured ? '#10b981' : '#ef4444'}
                  fillOpacity={isCaptured ? 0.8 : 0.2}
                  stroke="white"
                  strokeWidth="0.05"
                  className="transition-all duration-300"
                  filter={isCaptured ? 'url(#glow)' : ''}
                />
              );
            })}
          </g>

          {nextTargetSector !== -1 && (
            <g transform={`translate(50, 50) rotate(${(nextTargetSector * 360 / SECTOR_COUNT) + (180 / SECTOR_COUNT)})`}>
              <path 
                d="M -3 -46 L 0 -52 L 3 -46 Z" 
                fill="#3b82f6" 
                className="animate-bounce"
              />
            </g>
          )}
        </svg>
      </div>

      <div className="absolute inset-y-0 right-0 flex items-center pr-8 pointer-events-none z-30">
        <div className="relative">
          {isCapturing && (
            <div className="absolute inset-0 rounded-full bg-blue-400 animate-ping opacity-75 scale-125" />
          )}

          <button 
            onClick={captureFrame}
            disabled={state !== ScannerState.SCANNING}
            className={`pointer-events-auto w-24 h-24 rounded-full border-4 flex items-center justify-center transition-all hover:scale-110 active:scale-90 group shadow-2xl relative z-10 ${
              state === ScannerState.SCANNING 
                ? `${isCapturing ? 'border-blue-400 scale-105' : 'border-white/50'} bg-white/10 backdrop-blur-md cursor-pointer` 
                : 'border-slate-600 bg-slate-800/20 cursor-not-allowed opacity-50'
            }`}
            aria-label="Capture frame manually"
          >
            <div className={`w-18 h-18 rounded-full transition-all flex items-center justify-center ${
              isCapturing ? 'bg-blue-100' : 'bg-white group-hover:bg-blue-50'
            }`}>
               <div className="w-16 h-16 rounded-full border-2 border-slate-200 flex items-center justify-center">
                  <svg className={`w-10 h-10 transition-colors ${isCapturing ? 'text-blue-700' : 'text-blue-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
                  </svg>
               </div>
            </div>
          </button>
        </div>
      </div>

      <div className="absolute inset-0 pointer-events-none flex flex-col justify-between p-6 z-20">
        <div className="flex justify-between items-start">
          <div className="bg-black/70 backdrop-blur-lg px-4 py-2 rounded-2xl border border-white/10">
            <p className="text-[10px] uppercase font-bold text-blue-400 tracking-widest">{t.resolution}</p>
            <p className="text-lg font-mono font-bold">4K 60FPS</p>
          </div>
          <div className="bg-black/70 backdrop-blur-lg px-4 py-2 rounded-2xl border border-white/10 text-right">
            <p className="text-[10px] uppercase font-bold text-green-400 tracking-widest">{t.coverage}</p>
            <p className="text-xl font-mono font-bold">{Math.floor(coverage)}%</p>
          </div>
        </div>

        <div className="flex flex-col items-center gap-4 mb-4">
          <div className="bg-blue-600/95 backdrop-blur-md px-8 py-3 rounded-full border border-blue-400 shadow-[0_0_30px_rgba(59,130,246,0.3)] transition-all">
             <p className="text-xs font-black uppercase tracking-[0.2em] text-white">
               {coverage < 30 ? t.guide : (lang === 'es' ? 'CUBRA LAS ZONAS ROJAS' : lang === 'pt' ? 'CUBRA AS ZONAS VERMELHAS' : 'FOLLOW THE RED ZONES')}
             </p>
          </div>

          <div className="w-full max-w-sm h-2 bg-white/10 rounded-full overflow-hidden border border-white/5">
            <div 
              className="h-full bg-gradient-to-r from-blue-500 via-cyan-400 to-emerald-400 transition-all duration-300 shadow-[0_0_15px_rgba(59,130,246,0.6)]" 
              style={{ width: `${coverage}%` }}
            />
          </div>
        </div>
      </div>

      <div className="absolute inset-0 border-[20px] border-blue-500/5 pointer-events-none animate-pulse" />
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_transparent_0%,_rgba(0,0,0,0.4)_100%)] pointer-events-none" />

      {lightingStatus === 'dark' && (
        <div className="absolute inset-0 opacity-20 pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/p6.png')] contrast-200 brightness-50" />
      )}
    </div>
  );
};

