import React, { useState, useCallback } from 'react';
import AppHeader from './components/AppHeader';
import ScannerView from './components/ScannerView';
import KnowledgeHub from './components/KnowledgeHub';
import { ScannerState, CaptureFrame, ScanResult } from './types';
import { analyzeScanQuality } from './services/geminiScannerService';
import { translations, Language } from './translations';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('es');
  const [view, setView] = useState<'scanner' | 'knowledge'>('scanner');
  const [scannerState, setScannerState] = useState<ScannerState>(ScannerState.IDLE);
  const [capturedFrames, setCapturedFrames] = useState<CaptureFrame[]>([]);
  const [lastResult, setLastResult] = useState<ScanResult | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [feedback, setFeedback] = useState<string>('');

  const t = translations[lang];

  const handlePrintBase = () => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const htmlContent = `
      <html>
        <head>
          <title>PocketLab Calibration Base - Scale 1:1</title>
          <style>
            @page { size: A4; margin: 0; }
            body { font-family: sans-serif; padding: 20mm; text-align: center; color: #333; }
            .header { margin-bottom: 10mm; }
            .warning { color: red; font-weight: bold; margin-bottom: 5mm; font-size: 14px; }
            .base-container { 
              border: 1mm solid black; 
              width: 170mm; 
              height: 170mm; 
              margin: 0 auto; 
              position: relative; 
              background: #fff;
            }
            .marker { position: absolute; width: 25mm; height: 25mm; background: black; }
            .top-left { top: 0; left: 0; }
            .top-right { top: 0; right: 0; }
            .bottom-left { bottom: 0; left: 0; }
            .bottom-right { bottom: 0; right: 0; }
            .center-cross { 
              position: absolute; top: 50%; left: 50%; 
              transform: translate(-50%, -50%); 
              width: 100mm; height: 100mm; 
              border: 0.5mm dashed #ccc;
              display: flex; items-center; justify-content: center;
              font-size: 12px; color: #999;
            }
            .ruler {
              position: absolute; bottom: 10mm; left: 50%;
              transform: translateX(-50%);
              width: 100mm; height: 3mm; background: black;
            }
            .ruler-text { font-size: 10px; margin-top: 15mm; font-weight: bold; }
            .logo { font-weight: black; font-size: 24px; color: #1e40af; }
          </style>
        </head>
        <body>
          <div class="header">
            <div class="logo">PocketLab Dental</div>
            <p>Digital Extraoral Photogrammetry Base</p>
          </div>
          <div class="warning">
            IMPORTANT: PRINT AT 100% SCALE. DO NOT 'FIT TO PAGE'.<br/>
