            <div class="ruler-text">SCALE CHECK: THIS LINE MUST BE EXACTLY 100mm (10cm)</div>
          </div>
          <p style="margin-top: 10mm; font-size: 10px; color: #666;">
            &copy; 2024 PocketLab. High-precision clinical calibration system.
          </p>
          <script>
            window.onload = function() { window.print(); };
          </script>
        </body>
      </html>
    `;
    printWindow.document.write(htmlContent);
    printWindow.document.close();
  };

  const handleStartScan = () => {
    setCapturedFrames([]);
    setScannerState(ScannerState.SCANNING);
    setFeedback(lang === 'es' ? 'Mueva el celular lentamente alrededor del modelo.' : 'Move your phone slowly around the model.');
  };

  const handleFrameCapture = useCallback((frame: CaptureFrame) => {
